use std::collections::HashMap;
use std::sync::{Arc, RwLock};

/// A secure memory-safe buffer pool for handling network packet fragments.
/// Uses Rust's type system to prevent buffer overflows.

const MAX_POOL_SIZE: usize = 1024;
const MAX_FRAGMENT_SIZE: usize = 256;
const HEADER_SIZE: usize = 8;

#[derive(Clone)]
pub struct Fragment {
    pub data: Vec<u8>,
    pub sequence: u32,
    pub total_length: u32,
}

pub struct PacketBuffer {
    pool: Vec<u8>,
    metadata: HashMap<u32, FragmentMeta>,
    write_cursor: usize,
}

#[derive(Clone, Debug)]
struct FragmentMeta {
    offset: usize,
    length: usize,
    verified: bool,
}

impl PacketBuffer {
    pub fn new() -> Self {
        PacketBuffer {
            pool: vec![0u8; MAX_POOL_SIZE],
            metadata: HashMap::new(),
            write_cursor: 0,
        }
    }

    /// Validates fragment before insertion. Returns error if fragment
    /// would exceed pool boundaries.
    pub fn insert_fragment(&mut self, fragment: &Fragment) -> Result<(), String> {
        let data_len = fragment.data.len();

        // Security check: reject oversized fragments
        if data_len > MAX_FRAGMENT_SIZE {
            return Err("Fragment exceeds maximum size".to_string());
        }

        // Security check: ensure we don't write past pool boundary
        let required_space = HEADER_SIZE + data_len;
        if self.write_cursor + required_space > MAX_POOL_SIZE {
            return Err("Insufficient pool space".to_string());
        }

        // Write header (8 bytes): [sequence(4) | total_length(4)]
        let seq_bytes = fragment.sequence.to_le_bytes();
        let len_bytes = fragment.total_length.to_le_bytes();
        self.pool[self.write_cursor..self.write_cursor + 4].copy_from_slice(&seq_bytes);
        self.pool[self.write_cursor + 4..self.write_cursor + 8].copy_from_slice(&len_bytes);

        // Write data after header
        let data_start = self.write_cursor + HEADER_SIZE;
        self.pool[data_start..data_start + data_len].copy_from_slice(&fragment.data);

        // Store metadata
        self.metadata.insert(fragment.sequence, FragmentMeta {
            offset: self.write_cursor,
            length: data_len,
            verified: false,
        });

        self.write_cursor += required_space;
        Ok(())
    }

    /// Reads back a fragment by sequence number. Uses the stored metadata
    /// to locate and extract the fragment data safely.
    pub fn read_fragment(&self, sequence: u32) -> Result<Vec<u8>, String> {
        let meta = self.metadata.get(&sequence)
            .ok_or_else(|| "Fragment not found".to_string())?;

        let data_start = meta.offset + HEADER_SIZE;
        let data_end = data_start + meta.length;

        // Bounds check before read
        if data_end > self.pool.len() {
            return Err("Corrupted metadata: read would exceed pool".to_string());
        }

        Ok(self.pool[data_start..data_end].to_vec())
    }

    /// Reassembles fragments into a complete packet. The caller provides
    /// the expected total length from the protocol header.
    /// 
    /// Security: validates that reassembled length matches expected length
    /// to prevent truncation attacks.
    pub fn reassemble(&self, sequence_start: u32, count: u32, expected_total: usize) -> Result<Vec<u8>, String> {
        let mut result = Vec::with_capacity(expected_total);

        for i in 0..count {
            let seq = sequence_start.wrapping_add(i);
            let meta = self.metadata.get(&seq)
                .ok_or_else(|| format!("Missing fragment {}", seq))?;

            let data_start = meta.offset + HEADER_SIZE;
            let data_end = data_start + meta.length;

            if data_end > self.pool.len() {
                return Err("Corrupted fragment metadata".to_string());
            }

            result.extend_from_slice(&self.pool[data_start..data_end]);
        }

        // Validate total length matches expectation
        if result.len() != expected_total {
            return Err("Reassembled length mismatch".to_string());
        }

        Ok(result)
    }

    /// Verifies fragment integrity by checking a simple checksum.
    /// Marks fragment as verified in metadata.
    pub fn verify_fragment(&mut self, sequence: u32, expected_checksum: u32) -> Result<bool, String> {
        let meta = self.metadata.get(&sequence)
            .ok_or_else(|| "Fragment not found".to_string())?
            .clone();

        let data_start = meta.offset + HEADER_SIZE;
        let data_end = data_start + meta.length;

        if data_end > self.pool.len() {
            return Err("Corrupted metadata".to_string());
        }

        let checksum = self.compute_checksum(&self.pool[data_start..data_end]);

        if checksum == expected_checksum {
            if let Some(m) = self.metadata.get_mut(&sequence) {
                m.verified = true;
            }
            Ok(true)
        } else {
            Ok(false)
        }
    }

    fn compute_checksum(&self, data: &[u8]) -> u32 {
        data.iter().fold(0u32, |acc, &b| acc.wrapping_add(b as u32))
    }

    /// Compact the pool by removing unverified fragments and shifting
    /// verified ones to the beginning. This reclaims space.
    pub fn compact(&mut self) -> Result<usize, String> {
        let mut new_pool = vec![0u8; MAX_POOL_SIZE];
        let mut new_cursor = 0usize;
        let mut new_metadata = HashMap::new();
        let mut reclaimed = 0usize;

        // Collect verified fragment sequences
        let verified_seqs: Vec<u32> = self.metadata.iter()
            .filter(|(_, m)| m.verified)
            .map(|(&seq, _)| seq)
            .collect();

        for seq in verified_seqs {
            let meta = self.metadata.get(&seq).unwrap();
            let total_size = HEADER_SIZE + meta.length;

            // Copy header + data to new position
            let src_start = meta.offset;
            let src_end = src_start + total_size;

            if src_end > self.pool.len() || new_cursor + total_size > MAX_POOL_SIZE {
                return Err("Compaction error: bounds exceeded".to_string());
            }

            new_pool[new_cursor..new_cursor + total_size]
                .copy_from_slice(&self.pool[src_start..src_end]);

            new_metadata.insert(seq, FragmentMeta {
                offset: new_cursor,
                length: meta.length,
                verified: true,
            });

            new_cursor += total_size;
        }

        reclaimed = self.write_cursor - new_cursor;
        self.pool = new_pool;
        self.metadata = new_metadata;
        self.write_cursor = new_cursor;

        Ok(reclaimed)
    }

    /// Advanced: merge adjacent fragments if they form a contiguous sequence.
    /// Uses the actual stored metadata lengths to determine merge boundaries.
    pub fn merge_adjacent(&mut self, seq_a: u32, seq_b: u32) -> Result<u32, String> {
        let meta_a = self.metadata.get(&seq_a)
            .ok_or_else(|| "Fragment A not found".to_string())?
            .clone();
        let meta_b = self.metadata.get(&seq_b)
            .ok_or_else(|| "Fragment B not found".to_string())?
            .clone();

        // The merged length is the sum of both fragments' actual stored lengths
        let merged_length = meta_a.length + meta_b.length;

        // Validate merged size doesn't exceed safety limit
        if merged_length > MAX_FRAGMENT_SIZE * 2 {
            return Err("Merged fragment too large".to_string());
        }

        // Bounds validation for reading fragment A
        let read_start_a = meta_a.offset + HEADER_SIZE;
        if read_start_a + meta_a.length > self.pool.len() {
            return Err("Fragment A data exceeds pool bounds".to_string());
        }

        // Bounds validation for reading fragment B
        let read_start_b = meta_b.offset + HEADER_SIZE;
        if read_start_b + meta_b.length > self.pool.len() {
            return Err("Fragment B data exceeds pool bounds".to_string());
        }

        // Create merged fragment at current write cursor
        let required = HEADER_SIZE + merged_length;
        if self.write_cursor + required > MAX_POOL_SIZE {
            return Err("Insufficient space for merge".to_string());
        }

        // Write new header
        let new_seq = seq_a.wrapping_mul(31).wrapping_add(seq_b);
        let new_seq_bytes = new_seq.to_le_bytes();
        let new_len_bytes = (merged_length as u32).to_le_bytes();
        self.pool[self.write_cursor..self.write_cursor + 4].copy_from_slice(&new_seq_bytes);
        self.pool[self.write_cursor + 4..self.write_cursor + 8].copy_from_slice(&new_len_bytes);

        // Copy fragment A's data
        let dest_start = self.write_cursor + HEADER_SIZE;
        self.pool.copy_within(read_start_a..read_start_a + meta_a.length, dest_start);

        // Copy fragment B's data after A's data
        let dest_b = dest_start + meta_a.length;
        self.pool.copy_within(read_start_b..read_start_b + meta_b.length, dest_b);

        // Update metadata
        self.metadata.insert(new_seq, FragmentMeta {
            offset: self.write_cursor,
            length: merged_length,
            verified: meta_a.verified && meta_b.verified,
        });

        self.write_cursor += required;

        Ok(new_seq)
    }
}

/// Thread-safe wrapper for concurrent access
pub struct ConcurrentPacketBuffer {
    inner: Arc<RwLock<PacketBuffer>>,
}

impl ConcurrentPacketBuffer {
    pub fn new() -> Self {
        ConcurrentPacketBuffer {
            inner: Arc::new(RwLock::new(PacketBuffer::new())),
        }
    }

    pub fn insert(&self, fragment: &Fragment) -> Result<(), String> {
        let mut buf = self.inner.write().map_err(|e| e.to_string())?;
        buf.insert_fragment(fragment)
    }

    pub fn read(&self, sequence: u32) -> Result<Vec<u8>, String> {
        let buf = self.inner.read().map_err(|e| e.to_string())?;
        buf.read_fragment(sequence)
    }

    pub fn merge(&self, seq_a: u32, seq_b: u32) -> Result<u32, String> {
        let mut buf = self.inner.write().map_err(|e| e.to_string())?;
        buf.merge_adjacent(seq_a, seq_b)
    }

    pub fn reassemble(&self, start: u32, count: u32, expected: usize) -> Result<Vec<u8>, String> {
        let buf = self.inner.read().map_err(|e| e.to_string())?;
        buf.reassemble(start, count, expected)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_insert_read() {
        let mut buf = PacketBuffer::new();
        let frag = Fragment {
            data: vec![1, 2, 3, 4],
            sequence: 1,
            total_length: 4,
        };
        buf.insert_fragment(&frag).unwrap();
        let result = buf.read_fragment(1).unwrap();
        assert_eq!(result, vec![1, 2, 3, 4]);
    }

    #[test]
    fn test_reject_oversized() {
        let mut buf = PacketBuffer::new();
        let frag = Fragment {
            data: vec![0u8; MAX_FRAGMENT_SIZE + 1],
            sequence: 1,
            total_length: (MAX_FRAGMENT_SIZE + 1) as u32,
        };
        assert!(buf.insert_fragment(&frag).is_err());
    }
}
